def status_category(code):
    if 200 <= code < 300:
        return 'success'
    if 300 <= code < 400:
        return 'redirect'
    if 400 <= code < 500:
        return 'client_error'
    if 500 <= code < 600:
        return 'server_error'
    return 'other'
